(7594154, 1224961, 52549, '<td valign="top">My favourite so far. Beautiful image.</td>', 'My favourite so far. Beautiful image.', '2018-08-28 06:48:58.000000', NULL, 1),
(7594155, 1224993, 52549, '<td valign="top">Lovely scene. I think I would have cropped it slightly more at the bottom. The light coloured water (bottom middle) is rather distracting.</td>', 'Lovely scene. I think I would have cropped it slightly more at the bottom. The light coloured water (bottom middle) is rather distracting.', '2018-08-28 06:52:51.000000', NULL, 1),
