(7594210, 1225171, 9668, '<td valign="top">Cool scene but feels fairly dark. Not how well the BW style works on this.</td>', 'Cool scene but feels fairly dark. Not how well the BW style works on this.', '2018-08-28 18:40:33.000000', NULL, 1),
(7594264, 1224971, 241259, '<td valign="top">https://www.dpchallenge.com/challenge_vote_image.php?IMAGE_ID=1224971#</td>', 'https://www.dpchallenge.com/challenge_vote_image.php?IMAGE_ID=1224971#', '2018-08-29 01:08:59.000000', NULL, 1),
(7594294, 1224997, 67258, '<td valign="top">Love the way the composition draws the eye around - the crashing wave on the left edge , and the mirrored rolling wave on the right are the perfect touch. Just within the bounds of acceptable sharpening - another degree and it would have taken it over.  As it is there does seem to be the start of haloing in places.  Nonetheless, cracking shot.</td>', 'Love the way the composition draws the eye around - the crashing wave on the left edge , and the mirrored rolling wave on the right are the perfect touch. Just within the bounds of acceptable sharpening - another degree and it would have taken it over.  As it is there does seem to be the start of haloing in places.  Nonetheless, cracking shot.', '2018-08-29 08:04:43.000000', NULL, 1),
(7594295, 1224941, 67258, '<td valign="top">A pleasing image, but not the strongest composition for this specific challenge.</td>', 'A pleasing image, but not the strongest composition for this specific challenge.', '2018-08-29 08:05:22.000000', NULL, 1),
(7594297, 1224952, 67258, '<td valign="top">Interesting rock formations, and your toning adds (in a positive way) to the strangeness.  I don''t really get the inclusion of the wheel hubs, and in any event, I feel that to be truly effective as foreground interest, they need to be more prominent, perhaps from a lower view point.</td>', 'Interesting rock formations, and your toning adds (in a positive way) to the strangeness.  I don''t really get the inclusion of the wheel hubs, and in any event, I feel that to be truly effective as foreground interest, they need to be more prominent, perhaps from a lower view point.', '2018-08-29 08:09:11.000000', NULL, 1),
(7594298, 1225182, 67258, '<td valign="top">A pleasing photo, with a composition that draws my eyes from lower left, along the line of yellow flowers, to the trees, across to the barn and then to the misted tree line behind.</td>', 'A pleasing photo, with a composition that draws my eyes from lower left, along the line of yellow flowers, to the trees, across to the barn and then to the misted tree line behind.', '2018-08-29 08:10:52.000000', NULL, 1),
(7594299, 1224973, 67258, '<td valign="top">Absolutely intriguing photo, and certainly meets the challenge theme in spades.  Something about the toning is off for me, which is a shame.</td>', 'Absolutely intriguing photo, and certainly meets the challenge theme in spades.  Something about the toning is off for me, which is a shame.', '2018-08-29 08:12:34.000000', NULL, 1),
(7594300, 1225035, 67258, '<td valign="top">I''m going to hazard this could be on Skye.  A delightful scene - I''m not usually overly keen on this type of HDR style toning, but here it works really well.  My only negative point is that the placement of the orange flowers is very slightly off, perhaps too close to the centre line, for my eye.</td>', 'I''m going to hazard this could be on Skye.  A delightful scene - I''m not usually overly keen on this type of HDR style toning, but here it works really well.  My only negative point is that the placement of the orange flowers is very slightly off, perhaps too close to the centre line, for my eye.', '2018-08-29 08:14:35.000000', NULL, 1),
(7594301, 1225190, 67258, '<td valign="top">Pretty falls, and a competently taken photo, but for me misses the ''background'' layered element the challenge calls for.</td>', 'Pretty falls, and a competently taken photo, but for me misses the ''background'' layered element the challenge calls for.', '2018-08-29 08:15:44.000000', NULL, 1),
(7594302, 1225151, 67258, '<td valign="top">A really pleasing coastal seaside photo, but missing the pull in the background layer (almost by definition, given the subject) for me to score highly for this particular challenge.</td>', 'A really pleasing coastal seaside photo, but missing the pull in the background layer (almost by definition, given the subject) for me to score highly for this particular challenge.', '2018-08-29 08:17:35.000000', NULL, 1),
(7594304, 1224961, 67258, '<td valign="top">The mist adds a lovely element to this photo.  Computationally, for this specific challenge, lacks the effective use of foreground called for.  I do wonder if you had cropped this panoramic style, if it would have worked better, with the reflection becoming the foreground lead-in.  Nonetheless, a pleasing photo.</td>', 'The mist adds a lovely element to this photo.  Computationally, for this specific challenge, lacks the effective use of foreground called for.  I do wonder if you had cropped this panoramic style, if it would have worked better, with the reflection becoming the foreground lead-in.  Nonetheless, a pleasing photo.', '2018-08-29 08:19:54.000000', NULL, 1),
(7594312, 1225217, 67258, '<td valign="top">Pleasingly delicate.</td>', 'Pleasingly delicate.', '2018-08-29 09:51:49.000000', NULL, 1),
(7594313, 1224947, 67258, '<td valign="top">Strong on the centre ground, but less so for foreground and background - for me this misses the mark for the specific challenge.</td>', 'Strong on the centre ground, but less so for foreground and background - for me this misses the mark for the specific challenge.', '2018-08-29 09:53:08.000000', NULL, 1),
(7594314, 1225078, 67258, '<td valign="top">A competent photo, but the whole is somehow less than the sum of its parts.</td>', 'A competent photo, but the whole is somehow less than the sum of its parts.', '2018-08-29 09:54:37.000000', NULL, 1),
(7594315, 1225141, 67258, '<td valign="top">An interesting treatment - perhaps a bit to kitsch for my tastes, almost with a nod to the style of Thomas Kincade -  but a super composition and overall, a pleasing scene.</td>', 'An interesting treatment - perhaps a bit to kitsch for my tastes, almost with a nod to the style of Thomas Kincade -  but a super composition and overall, a pleasing scene.', '2018-08-29 09:56:24.000000', NULL, 1),
