(7594713, 1225033, 87808, '<td valign="top">A 10 from me, gorgeous!</td>', 'A 10 from me, gorgeous!', '2018-09-02 00:32:52.000000', NULL, 1),
(7594714, 1225051, 87808, '<td valign="top">This is stunning, it is called Smoke Inversion, I was lucky to enough to capture this in some shots from a wild fire years ago.  It is stunningly gorgeous, but a terrible thing at the same time. You have captured it beautifully.  Hope this clears up quickly for your area. 10</td>', 'This is stunning, it is called Smoke Inversion, I was lucky to enough to capture this in some shots from a wild fire years ago.  It is stunningly gorgeous, but a terrible thing at the same time. You have captured it beautifully.  Hope this clears up quickly for your area. 10', '2018-09-02 00:32:59.000000', NULL, 1),
(7594717, 1224976, 87808, '<td valign="top">All so brilliantly captured here, the cliffs, the smooth sails, the itty bitty sails in the distance, great capture</td>', 'All so brilliantly captured here, the cliffs, the smooth sails, the itty bitty sails in the distance, great capture', '2018-09-02 00:34:25.000000', NULL, 1),
